// #ebdb2f (6a993d7890d7492f45ebdb2f) AC4 — מנהל/ת מגייס/ת не попадает в настройки бизнеса. Кейс BSET-006.
// Роль: user (מנהל/ת מגייס/ת testim, сохранённая сессия .qa/auth/user.json, без пароля). Только чтение → @prod-safe.
import * as path from 'path';
import { test, expect } from '@playwright/test';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user.json') });

const TAG = '#ebdb2f · #6a993d7890d7492f45ebdb2f';

test.describe(`Настройки бизнеса — отказ מנהל/ת מגייס/ת (${TAG})`, () => {
  test(`BSET-006: /settings/business → «אין לכם גישה לעמוד הזה» с указанием обратиться к מנהל החשבון, формы нет, данные настроек не запрашиваются, «חזרה לדשבורד» → / @desktop @prod-safe ${TAG}`, async ({ page }) => {
    const settingsReads: string[] = [];
    page.on('request', (r) => {
      const u = decodeURIComponent(r.url());
      // Запрос формы настроек: select из businesses с contact_role / candidate_legal_text (S-06).
      if (u.includes('/rest/v1/businesses') && /contact_role|candidate_legal_text/.test(u)) settingsReads.push(u.slice(0, 160));
    });

    await page.goto('/settings/business');

    // Источник: AC4 «הגישה נדחית»; FL-10 шаг 2 — «מציינת למי לפנות לשינוי הרשאה ואינה חושפת את תוכן הגדרות העסק».
    const denied = page.getByTestId('access-denied');
    await expect(denied).toBeVisible();
    await expect(denied.getByRole('heading', { name: 'אין לכם גישה לעמוד הזה' })).toBeVisible();
    await expect(denied).toContainText('פנו למנהל החשבון בעסק שלכם');
    await expect(page.getByRole('textbox', { name: 'שם העסק', exact: true })).toHaveCount(0);
    await expect(page.getByLabel('שפת ברירת מחדל')).toHaveCount(0);
    await expect(page.getByTestId('quota-card')).toHaveCount(0);
    expect(settingsReads, 'данные настроек бизнеса запрошены').toEqual([]);

    // В меню роли нет пункта «הגדרות».
    await expect(page.getByRole('link', { name: 'הגדרות', exact: true })).toHaveCount(0);

    // FL-10: «מוחזר לדשבורד».
    await denied.getByRole('link', { name: 'חזרה לדשבורד' }).click();
    await page.waitForURL((u) => u.pathname === '/');
  });
});
